import type { Readable } from 'node:stream';

export interface StoredObjectMetadata {
  readonly contentType: string;
  readonly sizeBytes: number;
}

/** S3-compatible object storage (RustFS locally). Keys are generated by the application. */
export interface ObjectStorage {
  putObject(key: string, body: Buffer, contentType: string): Promise<void>;
  getObject(key: string): Promise<{ body: Readable; metadata: StoredObjectMetadata }>;
  deleteObject(key: string): Promise<void>;
  /** Short-lived signed download URL, or null when signing is not configured. */
  signedDownloadUrl(
    key: string,
    expiresInSeconds: number,
    fileName: string,
  ): Promise<string | null>;
  checkHealth(): Promise<boolean>;
}
